/**
 * A harmonia oculta na música — o monocórdio de Pitágoras.
 *
 * Uma corda esticada, um cavalete que anda, e a descoberta: os comprimentos que
 * soam bem são exatamente as frações SIMPLES da corda inteira. Metade dá a
 * oitava, dois terços a quinta, três quartos a quarta. Entre elas, arranha.
 *
 * A cena desenha os trastes nas posições que o renderizador declara em
 * `NOTAS_MUSICA` — a mesma lista que escreve a leitura, para o traste desenhado
 * e a nota anunciada nunca discordarem. O trecho que vibra vibra de verdade: a
 * onda estacionária tem tantos ventres quanto a razão pede, e é isso que mostra
 * por que uma fração simples "casa".
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import { NOTAS_MUSICA } from '../renderizadores/fisica.ts';
import {
  type EstadoDaViz,
  etiqueta,
  infoDe,
  limitar,
  MATERIAIS,
  numeroDe,
  paleta,
  retangulo,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const TAMPO = '#c99a5e';
const TAMPO_ESCURO = '#a97c45';

const musica: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const comprimento = limitar(numeroDe(valores, 'comp', 100), 1, 100);
    const consonante = info.consonante === true;
    const ok = info.ok === true;
    const tinta = ok ? cor.verde : consonante ? cor.azul : cor.fraco;
    const miudo = limitar(A * 0.03, 8, 11);

    titulo(ctx, L, A, 'A corda pela metade soa a mesma nota, uma oitava acima');

    // ── A caixa do monocórdio ─────────────────────────────────────────────
    const x0 = L * 0.08;
    const x1 = L * 0.92;
    const yCorda = A * 0.44;
    const alturaCaixa = A * 0.16;

    const tampo = ctx.createLinearGradient(0, yCorda, 0, yCorda + alturaCaixa);
    tampo.addColorStop(0, TAMPO);
    tampo.addColorStop(1, TAMPO_ESCURO);
    retangulo(ctx, x0 - 10, yCorda, x1 - x0 + 20, alturaCaixa, 6, tampo, cor.texto, 1.4);

    // A boca da caixa, para ela ler como instrumento.
    ctx.fillStyle = 'rgb(60 40 20 / 55%)';
    ctx.beginPath();
    ctx.ellipse(
      (x0 + x1) / 2,
      yCorda + alturaCaixa * 0.55,
      alturaCaixa * 0.28,
      alturaCaixa * 0.28,
      0,
      0,
      Math.PI * 2,
    );
    ctx.fill();

    // ── Os trastes: as frações que casam ──────────────────────────────────
    // A corda inteira é 100%; o cavalete anda da direita para a esquerda, e o
    // trecho VIBRANTE é o da esquerda até ele.
    const px = (percentual: number): number => x0 + (percentual / 100) * (x1 - x0);

    for (const nota of NOTAS_MUSICA) {
      const x = px(nota.p);
      const perto = Math.abs(comprimento - nota.p) <= 1.2;

      ctx.strokeStyle = perto ? cor.azul : cor.trilho;
      ctx.lineWidth = perto ? 2 : 1.2;
      ctx.beginPath();
      ctx.moveTo(x, yCorda - A * 0.16);
      ctx.lineTo(x, yCorda);
      ctx.stroke();

      texto(ctx, nota.frac, x, yCorda - A * 0.185, miudo * 0.9, {
        cor: perto ? cor.azul : cor.fraco,
        peso: perto ? 800 : 600,
      });
    }

    // ── A corda, com a onda estacionária no trecho que vibra ──────────────
    const xCavalete = px(comprimento);

    // A parte morta, à direita do cavalete: existe, mas não soa.
    ctx.strokeStyle = cor.trilho;
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(xCavalete, yCorda - A * 0.02);
    ctx.lineTo(x1, yCorda - A * 0.02);
    ctx.stroke();

    // Quantos ventres: a razão entre a corda inteira e o trecho — 1/2 dá dois.
    const modos = Math.max(1, Math.round(100 / comprimento));
    const amplitude = A * 0.045 * (consonante ? 1 : 0.45);

    ctx.strokeStyle = tinta;
    ctx.lineWidth = 2.6;
    ctx.lineJoin = 'round';
    ctx.beginPath();
    for (let i = 0; i <= 120; i++) {
      const u = i / 120;
      const x = x0 + u * (xCavalete - x0);
      // Onda estacionária: nós nas pontas, e o "arranhar" entra como ruído.
      const puro = Math.sin(u * Math.PI * modos) * Math.sin(t * 9);
      const sujo = consonante ? 0 : Math.sin(u * Math.PI * 17.3 + t * 21) * 0.45;
      const y = yCorda - A * 0.02 + (puro + sujo) * amplitude;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // O cavalete que o slider move.
    retangulo(
      ctx,
      xCavalete - 4,
      yCorda - A * 0.075,
      8,
      A * 0.075,
      2,
      MATERIAIS.madeiraClara,
      cor.texto,
      1.2,
    );

    // Os dois cepos das pontas.
    for (const x of [x0, x1]) {
      retangulo(ctx, x - 4, yCorda - A * 0.055, 8, A * 0.055, 2, MATERIAIS.madeira, cor.texto, 1.2);
    }

    // ── A leitura da nota ─────────────────────────────────────────────────
    const nota = info.nota as { nome?: string; nota?: string; razao?: string } | null | undefined;

    etiqueta(
      ctx,
      consonante && nota?.nome !== undefined
        ? `${nota.nome} (${nota.nota}) · ${nota.razao}`
        : 'arranha — não é fração simples',
      (x0 + xCavalete) / 2,
      yCorda + alturaCaixa + miudo * 2.2,
      miudo * 1.05,
      tinta,
      800,
    );

    texto(
      ctx,
      `${comprimento.toFixed(1).replace('.', ',')}% da corda vibra`,
      L / 2,
      A * 0.88,
      miudo,
      { cor: cor.fraco, peso: 700 },
    );

    rodape(
      ctx,
      L,
      A,
      ok,
      'Oitava: a corda pela metade, o dobro da frequência ✔',
      consonante
        ? 'Bonito, mas o desafio pede a OITAVA — a corda pela metade.'
        : 'Deslize até uma das frações marcadas.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default musica;
